        // Iterable → GenericArrayData (ListState returns Iterable)
        GenericArrayData fromIterable =
                (GenericArrayData)
                        InternalTypeConverter.toInternal(
                                Arrays.asList(10L, 20L), new ArrayType(new BigIntType()));
