    /**
     * Checks the given boolean condition, and throws an {@code IllegalArgumentException} if the
     * condition is not met (evaluates to {@code false}).
     *
     * @param condition The condition to check
     * @throws IllegalArgumentException Thrown, if the condition is violated.
     */
public static void checkArgument(boolean condition) {
        if (!condition) {
            throw new IllegalArgumentException();
        }
    }

/**
     * Checks the given boolean condition, and throws an {@code IllegalArgumentException} if the
     * condition is not met (evaluates to {@code false}). The exception will have the given error
     * message.
     *
     * @param condition The condition to check
     * @param errorMessage The message for the {@code IllegalArgumentException} that is thrown if
     *     the check fails.
     * @throws IllegalArgumentException Thrown, if the condition is violated.
     */
public static void checkArgument(boolean condition, @Nullable Object errorMessage) {
        if (!condition) {
            throw new IllegalArgumentException(String.valueOf(errorMessage));
        }
    }

private List<String> deriveNaturalJoinColumnList(SqlJoin join) {
        return SqlValidatorUtil.deriveNaturalJoinColumnList(
                catalogReader.nameMatcher(),
                getNamespaceOrThrow(join.getLeft()).getRowType(),
                getNamespaceOrThrow(join.getRight()).getRowType());
    }

private SqlValidatorScope getScopeOrThrow(SqlNode node) {
        return requireNonNull(scopes.get(node), () -> "scope for " + node);
    }

